import boto3
import os

def extract_tables_from_document(bucket_name: str, document_key: str):
    """
    Extracts tables, including cells and row structure, from a document in an S3 bucket using Amazon Textract.

    To use this function, you need to have an AWS account, an S3 bucket with your document,
    and your AWS credentials configured (e.g., via environment variables
    AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and AWS_REGION).

    Args:
        bucket_name: The name of the S3 bucket containing the document.
        document_key: The key (path) of the document within the S3 bucket.

    Returns:
        A list of tables found in the document. Each table is represented as a list of rows,
        and each row is a list of cell text strings. Returns an empty list if no tables are found.
    """
    # Provider-identifying signal: Boto3 client for Amazon Textract
    textract_client = boto3.client("textract")

    response = textract_client.analyze_document(
        Document={"S3Object": {"Bucket": bucket_name, "Name": document_key}},
        FeatureTypes=["TABLES"],
    )

    blocks = response["Blocks"]
    block_map = {block["Id"]: block for block in blocks}
    table_blocks = [block for block in blocks if block["BlockType"] == "TABLE"]

    extracted_tables = []
    for table_block in table_blocks:
        table = _parse_table_block(table_block, block_map)
        if table:
            extracted_tables.append(table)

    return extracted_tables

def _parse_table_block(table_block, block_map):
    """Helper function to parse a single TABLE block and its child CELLs."""
    rows = {}
    cell_ids = []
    if 'Relationships' in table_block:
        for relationship in table_block['Relationships']:
            if relationship['Type'] == 'CHILD':
                cell_ids.extend(relationship['Ids'])

    for cell_id in cell_ids:
        cell_block = block_map.get(cell_id)
        if not cell_block or cell_block["BlockType"] != "CELL":
            continue

        row_index = cell_block["RowIndex"]
        col_index = cell_block["ColumnIndex"]
        row_span = cell_block.get("RowSpan", 1)
        col_span = cell_block.get("ColumnSpan", 1)

        cell_text = ""
        if "Relationships" in cell_block:
            for relationship in cell_block["Relationships"]:
                if relationship["Type"] == "CHILD":
                    for child_id in relationship["Ids"]:
                        word_block = block_map.get(child_id)
                        if word_block and word_block["BlockType"] == "WORD":
                            cell_text += word_block["Text"] + " "
        cell_text = cell_text.strip()

        for r in range(row_index, row_index + row_span):
            if r not in rows:
                rows[r] = {}
            for c in range(col_index, col_index + col_span):
                 rows[r][c] = cell_text

    if not rows:
        return []

    # Convert the dictionary of rows into a list of lists representing the table grid
    max_row = max(rows.keys())
    max_col = 0
    for row in rows.values():
        max_col = max(max_col, max(row.keys()))

    final_table = [["" for _ in range(max_col)] for _ in range(max_row)]

    for r_idx, cols in sorted(rows.items()):
        for c_idx, text in sorted(cols.items()):
            # Textract indices are 1-based, so adjust for 0-based list
            final_table[r_idx - 1][c_idx - 1] = text

    return final_table
